import { useState, useEffect, useRef } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Menu, X, Heart, Home, Shield, Globe, Users, Hand, Megaphone, Droplet,
  ChevronLeft, ChevronRight, Star, Mail, Phone, MapPin
} from 'lucide-react'
import { siteConfig } from './config/site'

const { brand, header, hero, mission, impactStats, programs, getInvolved, news, donateCta, footer } = siteConfig

// Counter animation hook
function useCountUp(end: number, duration: number = 2000, start: boolean = true) {
  const [count, setCount] = useState(0)
  const [hasStarted, setHasStarted] = useState(false)

  useEffect(() => {
    if (!start) return
    if (hasStarted) return

    setHasStarted(true)
    const startTime = Date.now()
    const updateCount = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      setCount(Math.floor(eased * end))
      if (progress < 1) requestAnimationFrame(updateCount)
    }
    requestAnimationFrame(updateCount)
  }, [end, duration, start, hasStarted])

  return count
}

// Intersection Observer hook
function useInView(ref: React.RefObject<HTMLElement>, threshold = 0.1) {
  const [inView, setInView] = useState(false)
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry.isIntersecting),
      { threshold }
    )
    if (ref.current) observer.observe(ref.current)
    return () => observer.disconnect()
  }, [ref, threshold])
  return inView
}

// Header Component
function Header({ onDonateClick }: { onDonateClick: () => void }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  return (
    <header className="fixed top-0 left-0 right-0 z-40 bg-white border-b border-gray-100">
      <div className="max-w-7xl mx-auto px-4 lg:px-8">
        <div className="flex items-center justify-between h-16 lg:h-20">
          {/* Logo */}
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ backgroundColor: brand.primaryRed }}>
              <Heart className="w-5 h-5 text-white" />
            </div>
            <div>
              <span className="font-bold text-lg text-gray-900">Global Aid Alliance</span>
              <span className="hidden sm:block text-xs text-gray-500">{header.utilityLinks[2]}</span>
            </div>
          </div>

          {/* Desktop Nav */}
          <nav className="hidden lg:flex items-center gap-8">
            {header.nav.map((link) => (
              <a key={link.label} href={link.href} className="text-sm font-medium text-gray-700 hover:text-gray-900 transition-colors">
                {link.label}
              </a>
            ))}
          </nav>

          {/* Desktop Actions */}
          <div className="hidden lg:flex items-center gap-4">
            <div className="flex items-center gap-4 text-sm text-gray-500">
              {header.utilityLinks.slice(0, 2).map((link) => (
                <a key={link} href="#" className="hover:text-gray-900 transition-colors">{link}</a>
              ))}
            </div>
            <button
              onClick={onDonateClick}
              className="px-5 py-2.5 rounded-md text-white font-semibold text-sm transition-transform hover:scale-105"
              style={{ backgroundColor: brand.primaryRed }}
            >
              {header.donateLabel}
            </button>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="lg:hidden p-2 rounded-md hover:bg-gray-100"
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {mobileMenuOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.3 }}
            className="lg:hidden overflow-hidden bg-white border-t"
          >
            <div className="px-4 py-4 space-y-2">
              {header.nav.map((link) => (
                <a
                  key={link.label}
                  href={link.href}
                  className="block py-2 text-gray-700 font-medium"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {link.label}
                </a>
              ))}
              <div className="pt-4 border-t mt-4">
                <div className="flex gap-4 text-sm text-gray-500 mb-4">
                  {header.utilityLinks.slice(0, 2).map((link) => (
                    <a key={link} href="#" className="hover:text-gray-900">{link}</a>
                  ))}
                </div>
                <button
                  onClick={() => { onDonateClick(); setMobileMenuOpen(false) }}
                  className="w-full py-3 rounded-md text-white font-semibold"
                  style={{ backgroundColor: brand.primaryRed }}
                >
                  {header.donateLabel}
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  )
}

// Hero Section
function Hero({ onDonateClick }: { onDonateClick: () => void }) {
  return (
    <section className="pt-20 lg:pt-24 bg-gradient-to-b from-gray-50 to-white">
      <div className="max-w-7xl mx-auto px-4 lg:px-8 py-12 lg:py-20">
        <div className="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <motion.span
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
              className="inline-block px-3 py-1 rounded-full text-xs font-semibold text-white mb-6"
              style={{ backgroundColor: brand.navyBlue }}
            >
              {hero.badge}
            </motion.span>
            <motion.h1
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.1 }}
              className="text-4xl md:text-5xl lg:text-6xl font-bold text-gray-900 leading-tight mb-6"
            >
              {hero.title.split('\n').map((line, i) => (
                <span key={i}>{i === 1 ? <span style={{ color: brand.primaryRed }}>{line}</span> : line}<br /></span>
              ))}
            </motion.h1>
            <motion.p
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.2 }}
              className="text-lg text-gray-600 mb-8 leading-relaxed"
            >
              {hero.subtitle}
            </motion.p>
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.3 }}
              className="flex flex-wrap gap-4"
            >
              <button
                onClick={onDonateClick}
                className="px-8 py-4 rounded-md text-white font-bold text-lg transition-transform hover:scale-105 shadow-lg"
                style={{ backgroundColor: brand.primaryRed }}
              >
                {hero.primaryCta.text}
              </button>
              <a
                href={hero.secondaryCta.href}
                className="px-8 py-4 rounded-md border-2 font-semibold text-lg transition-colors hover:bg-gray-50"
                style={{ borderColor: brand.navyBlue, color: brand.navyBlue }}
              >
                {hero.secondaryCta.text}
              </a>
            </motion.div>
          </div>
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8, delay: 0.2 }}
            className="relative"
          >
            <div className="aspect-square rounded-2xl overflow-hidden bg-gradient-to-br from-red-50 to-blue-50 p-8 flex items-center justify-center">
              <div className="grid grid-cols-2 gap-4 w-full max-w-sm">
                {[
                  { icon: Heart, label: 'Lives Saved', value: '2.5M+' },
                  { icon: Globe, label: 'Countries', value: '190' },
                  { icon: Users, label: 'Volunteers', value: '50K+' },
                  { icon: Shield, label: 'Relief Ops', value: '12K+' },
                ].map((stat, i) => (
                  <motion.div
                    key={stat.label}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.4 + i * 0.1 }}
                    className="bg-white rounded-xl p-4 shadow-md text-center"
                  >
                    <stat.icon className="w-8 h-8 mx-auto mb-2" style={{ color: brand.primaryRed }} />
                    <div className="text-2xl font-bold text-gray-900">{stat.value}</div>
                    <div className="text-xs text-gray-500">{stat.label}</div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

// Mission Section
function Mission() {
  return (
    <section className="py-16 lg:py-24 bg-white">
      <div className="max-w-4xl mx-auto px-4 lg:px-8 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-8">{mission.title}</h2>
        <div className="prose prose-lg text-gray-600">
          {mission.text.split('\n\n').map((para, i) => (
            <p key={i} className="mb-4">{para}</p>
          ))}
        </div>
      </div>
    </section>
  )
}

// Impact Stats Section
function ImpactStats() {
  const ref = useRef<HTMLElement>(null)
  const inView = useInView(ref)

  return (
    <section ref={ref} className="py-16 lg:py-24 bg-gray-900">
      <div className="max-w-7xl mx-auto px-4 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">Our Impact</h2>
          <p className="text-gray-400 text-lg">Real lives changed across the globe</p>
        </div>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 lg:gap-8">
          {impactStats.map((stat, i) => (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 30 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="text-center p-6 rounded-xl bg-gray-800 border border-gray-700"
            >
              <div className="text-4xl md:text-5xl font-bold text-white mb-2">{stat.display}</div>
              <div className="text-sm text-gray-400">{stat.label}</div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}

// Programs Section
function Programs() {
  const [openItem, setOpenItem] = useState<string | null>(null)

  return (
    <section className="py-16 lg:py-24 bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 lg:px-8">
