              <Heart className="w-5 h-5 text-white" />
            </div>
            <div>
              <span className="font-bold text-lg text-gray-900">Global Aid Alliance</span>
              <span className="hidden sm:block text-xs text-gray-500">{header.utilityLinks[2]}</span>
            </div>
