          {/* Desktop Nav */}
          <nav className="hidden lg:flex items-center gap-8">
            {header.nav.map((link) => (
              <a key={link.label} href={link.href} className="text-sm font-medium text-gray-700 hover:text-gray-900 transition-colors">
                {link.label}
              </a>
