                    className="bg-white rounded-xl p-4 shadow-md text-center"
                  >
                    <stat.icon className="w-8 h-8 mx-auto mb-2" style={{ color: brand.primaryRed }} />
                    <div className="text-2xl font-bold text-gray-900">{stat.value}</div>
                    <div className="text-xs text-gray-500">{stat.label}</div>
                  </motion.div>
                ))}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  )
}

// Mission Section
function Mission() {
  return (
    <section className="py-16 lg:py-24 bg-white">
      <div className="max-w-4xl mx-auto px-4 lg:px-8 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-8">{mission.title}</h2>
        <div className="prose prose-lg text-gray-600">
          {mission.text.split('\n\n').map((para, i) => (
            <p key={i} className="mb-4">{para}</p>
          ))}
        </div>
      </div>
    </section>
  )
}

// Impact Stats Section
function ImpactStats() {
  const ref = useRef<HTMLElement>(null)
  const inView = useInView(ref)

  return (
    <section ref={ref} className="py-16 lg:py-24 bg-gray-900">
      <div className="max-w-7xl mx-auto px-4 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">Our Impact</h2>
          <p className="text-gray-400 text-lg">Real lives changed across the globe</p>
        </div>
        <div className="grid grid-cols-2 lg:grid-cols-4 gap-6 lg:gap-8">
          {impactStats.map((stat, i) => (
            <motion.div
              key={stat.label}
              initial={{ opacity: 0, y: 30 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="text-center p-6 rounded-xl bg-gray-800 border border-gray-700"
            >
              <div className="text-4xl md:text-5xl font-bold text-white mb-2">{stat.display}</div>
              <div className="text-sm text-gray-400">{stat.label}</div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  )
}

// Programs Section
function Programs() {
  const [openItem, setOpenItem] = useState<string | null>(null)

  return (
    <section className="py-16 lg:py-24 bg-gray-50">
      <div className="max-w-4xl mx-auto px-4 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">Programs & Services</h2>
          <p className="text-gray-600 text-lg">Comprehensive humanitarian support when and where it's needed most</p>
        </div>
        <div className="space-y-4">
          {programs.map((program) => {
            const isOpen = openItem === program.id
            return (
              <div key={program.id} className="bg-white rounded-xl overflow-hidden shadow-sm">
                <button
                  onClick={() => setOpenItem(isOpen ? null : program.id)}
                  className="w-full px-6 py-5 flex items-center justify-between text-left"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full flex items-center justify-center" style={{ backgroundColor: `${brand.primaryRed}15` }}>
                      {program.id === 'disaster-relief' && <Home className="w-6 h-6" style={{ color: brand.primaryRed }} />}
                      {program.id === 'blood-donation' && <Heart className="w-6 h-6" style={{ color: brand.primaryRed }} />}
                      {program.id === 'emergency-preparedness' && <Shield className="w-6 h-6" style={{ color: brand.primaryRed }} />}
                      {program.id === 'international-aid' && <Globe className="w-6 h-6" style={{ color: brand.primaryRed }} />}
                      {program.id === 'community-health' && <Users className="w-6 h-6" style={{ color: brand.primaryRed }} />}
                    </div>
                    <span className="font-semibold text-lg text-gray-900">{program.title}</span>
                  </div>
                  <motion.div
                    animate={{ rotate: isOpen ? 180 : 0 }}
                    transition={{ duration: 0.2 }}
                    className="w-6 h-6 text-gray-400"
                  >
                    <ChevronDown className="w-6 h-6" />
                  </motion.div>
                </button>
                <AnimatePresence>
                  {isOpen && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.3 }}
                      className="overflow-hidden"
                    >
                      <div className="px-6 pb-5 text-gray-600">
                        {program.description}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

// Get Involved Section
function GetInvolved() {
  const icons = { Hand, Megaphone, Droplet }

  return (
    <section className="py-16 lg:py-24 bg-white">
      <div className="max-w-7xl mx-auto px-4 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">Get Involved</h2>
          <p className="text-gray-600 text-lg">Multiple ways to make a difference</p>
        </div>
        <div className="grid md:grid-cols-3 gap-8">
          {getInvolved.map((item, i) => {
            const IconComponent = icons[item.icon as keyof typeof icons]
            return (
              <motion.div
                key={item.title}
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5, delay: i * 0.1 }}
                className="bg-gray-50 rounded-xl p-8 text-center"
              >
                <div className="w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6" style={{ backgroundColor: `${brand.navyBlue}15` }}>
                  <IconComponent className="w-8 h-8" style={{ color: brand.navyBlue }} />
                </div>
                <h3 className="text-xl font-bold text-gray-900 mb-3">{item.title}</h3>
                <p className="text-gray-600 mb-6">{item.description}</p>
                <a
                  href="#"
                  className="inline-block px-6 py-3 rounded-md font-semibold transition-colors"
                  style={{ backgroundColor: brand.navyBlue, color: 'white' }}
                >
                  {item.cta}
                </a>
              </motion.div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

// News Section with Carousel
function News() {
  const [currentIndex, setCurrentIndex] = useState(0)
  const itemsPerPage = 3

  const nextSlide = () => setCurrentIndex((prev) => Math.min(prev + 1, news.length - itemsPerPage))
  const prevSlide = () => setCurrentIndex((prev) => Math.max(prev - 1, 0))

  return (
    <section className="py-16 lg:py-24 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 lg:px-8">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">Latest News</h2>
          <p className="text-gray-600 text-lg">Stories from the field</p>
        </div>
        <div className="relative">
          <div className="overflow-hidden">
            <div
              className="flex gap-6 transition-transform duration-300"
              style={{ transform: `translateX(-${currentIndex * (100 / itemsPerPage)}%)` }}
            >
              {news.map((item, i) => (
                <div key={i} className="flex-none w-full md:w-1/2 lg:w-1/3">
                  <div className="bg-white rounded-xl overflow-hidden shadow-sm h-full">
                    <div className="h-48 bg-gradient-to-br from-red-100 to-blue-100 flex items-center justify-center">
                      <span className="text-4xl font-bold" style={{ color: brand.primaryRed, opacity: 0.3 }}>0{i + 1}</span>
                    </div>
                    <div className="p-6">
                      <div className="flex items-center gap-2 mb-3">
                        <span className="px-2 py-1 rounded text-xs font-medium bg-gray-100 text-gray-600">{item.category}</span>
                        <span className="text-xs text-gray-400">{item.date}</span>
                      </div>
                      <h3 className="font-bold text-lg text-gray-900 mb-2">{item.title}</h3>
                      <p className="text-gray-600 text-sm">{item.excerpt}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="flex justify-center gap-4 mt-8">
            <button
              onClick={prevSlide}
              disabled={currentIndex === 0}
              className="w-12 h-12 rounded-full border-2 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:border-gray-400 transition-colors"
              style={{ borderColor: brand.navyBlue }}
            >
              <ChevronLeft className="w-5 h-5" style={{ color: brand.navyBlue }} />
            </button>
            <button
              onClick={nextSlide}
              disabled={currentIndex >= news.length - itemsPerPage}
              className="w-12 h-12 rounded-full border-2 flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed hover:border-gray-400 transition-colors"
              style={{ borderColor: brand.navyBlue }}
            >
              <ChevronRight className="w-5 h-5" style={{ color: brand.navyBlue }} />
            </button>
          </div>
        </div>
      </div>
    </section>
  )
}

// Donate CTA Section
function DonateCta({ onDonateClick }: { onDonateClick: () => void }) {
  return (
    <section className="py-16 lg:py-24 bg-gradient-to-br from-red-600 to-red-700">
      <div className="max-w-4xl mx-auto px-4 lg:px-8 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-white mb-4">{donateCta.title}</h2>
        <p className="text-red-100 text-lg mb-8">{donateCta.body}</p>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {donateCta.amounts.map((item) => (
            <button
              key={item.amount}
              onClick={onDonateClick}
              className="bg-white rounded-xl p-4 text-center hover:scale-105 transition-transform"
            >
              <div className="text-2xl font-bold text-gray-900">${item.amount}</div>
              <div className="text-xs text-gray-500 mt-1">{item.impact}</div>
            </button>
          ))}
        </div>
        <button
          onClick={onDonateClick}
          className="px-10 py-4 rounded-md bg-white text-red-600 font-bold text-lg hover:bg-red-50 transition-colors"
        >
          {donateCta.cta}
        </button>
      </div>
    </section>
  )
}

// Footer Component
function Footer() {
  return (
    <footer className="bg-gray-900 text-gray-300">
      <div className="max-w-7xl mx-auto px-4 lg:px-8 py-12">
        <div className="grid md:grid-cols-4 gap-8 mb-12">
          <div>
            <div className="flex items-center gap-2 mb-4">
              <div className="w-10 h-10 rounded-full flex items-center justify-center" style={{ backgroundColor: brand.primaryRed }}>
                <Heart className="w-5 h-5 text-white" />
              </div>
              <span className="font-bold text-white">Global Aid Alliance</span>
            </div>
            <p className="text-sm text-gray-400">Together we respond to disasters and build resilient communities worldwide.</p>
          </div>
          <div>
            <h4 className="font-semibold text-white mb-4">Programs</h4>
            <ul className="space-y-2 text-sm">
              {footer.programs.map((item) => (
                <li key={item}><a href="#" className="hover:text-white transition-colors">{item}</a></li>
              ))}
            </ul>
          </div>
          <div>
            <h4 className="font-semibold text-white mb-4">Get Involved</h4>
            <ul className="space-y-2 text-sm">
              {footer.getInvolved.map((item) => (
                <li key={item}><a href="#" className="hover:text-white transition-colors">{item}</a></li>
              ))}
            </ul>
          </div>
          <div>
            <h4 className="font-semibold text-white mb-4">About</h4>
            <ul className="space-y-2 text-sm">
              {footer.about.map((item) => (
                <li key={item}><a href="#" className="hover:text-white transition-colors">{item}</a></li>
              ))}
            </ul>
          </div>
        </div>
        <div className="border-t border-gray-800 pt-8 flex flex-col md:flex-row justify-between items-center gap-4">
          <p className="text-sm text-gray-500">{footer.tagline}</p>
          <div className="flex gap-4">
            {footer.social.map((social) => (
              <a key={social} href="#" className="text-gray-400 hover:text-white transition-colors">
                <span className="sr-only">{social}</span>
                <div className="w-8 h-8 rounded-full bg-gray-800 flex items-center justify-center">
                  <span className="text-xs">{social.charAt(0)}</span>
                </div>
              </a>
            ))}
          </div>
        </div>
      </div>
    </footer>
  )
}

// Donation Modal
function DonateModal({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  const [selectedAmount, setSelectedAmount] = useState<number | null>(25)
  const [customAmount, setCustomAmount] = useState('')

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 flex items-center justify-center p-4"
        >
          <motion.div
            initial={{ scale: 0.95, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            exit={{ scale: 0.95, opacity: 0 }}
            className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-8"
          >
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-gray-900">Make a Donation</h2>
              <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full">
                <X className="w-5 h-5" />
              </button>
            </div>
            <p className="text-gray-600 mb-6">Select or enter your donation amount</p>
            <div className="grid grid-cols-4 gap-3 mb-4">
              {[25, 50, 100, 250].map((amount) => (
                <button
                  key={amount}
                  onClick={() => setSelectedAmount(amount)}
                  className={`py-3 rounded-lg font-semibold transition-colors ${
                    selectedAmount === amount
                      ? 'text-white'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                  style={selectedAmount === amount ? { backgroundColor: brand.primaryRed } : {}}
                >
                  ${amount}
                </button>
              ))}
            </div>
            <div className="mb-6">
              <label className="block text-sm font-medium text-gray-700 mb-2">Custom Amount</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">$</span>
                <input
                  type="number"
                  value={customAmount}
                  onChange={(e) => {
                    setCustomAmount(e.target.value)
                    setSelectedAmount(null)
                  }}
                  placeholder="Enter amount"
                  className="w-full pl-8 pr-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-red-500"
                />
              </div>
            </div>
            <button
              className="w-full py-4 rounded-lg text-white font-bold text-lg transition-transform hover:scale-105"
              style={{ backgroundColor: brand.primaryRed }}
            >
              Donate {selectedAmount ? `$${selectedAmount}` : customAmount ? `$${customAmount}` : ''}
            </button>
            <p className="text-center text-xs text-gray-400 mt-4">
              91 cents of every dollar goes directly to humanitarian services
            </p>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

// Main App
export default function App() {
  const [donateModalOpen, setDonateModalOpen] = useState(false)

  return (
    <div className="min-h-screen bg-white">
      <Header onDonateClick={() => setDonateModalOpen(true)} />
      <main>
        <Hero onDonateClick={() => setDonateModalOpen(true)} />
        <Mission />
        <ImpactStats />
        <Programs />
        <GetInvolved />
        <News />
        <DonateCta onDonateClick={() => setDonateModalOpen(true)} />
      </main>
      <Footer />
      <DonateModal isOpen={donateModalOpen} onClose={() => setDonateModalOpen(false)} />
    </div>
  )
}

arguments.content:
@import "tailwindcss";

@theme {
  --color-primary-red: #C41E3A;
  --color-navy-blue: #1B3A5C;
  --color-white: #FFFFFF;
}

:root {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: light;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  min-height: 100vh;
}

* {
  box-sizing: border-box;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: #C41E3A;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #a01830;
}

/* Animation utilities */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.animate-fade-in-up {
  animation: fadeInUp 0.6s ease-out forwards;
}

.animate-pulse-slow {
  animation: pulse 3s ease-in-out infinite;
}

/* Smooth scrolling */
html {
  scroll-behavior: smooth;
}

/* Focus styles for accessibility */
button:focus-visible,
a:focus-visible {
  outline: 2px solid #C41E3A;
  outline-offset: 2px;
}

/* Prose styling for mission section */
.prose p {
  margin-bottom: 1rem;
}

/* Grid pattern background */
.bg-grid-pattern {
  background-image:
    linear-gradient(to right, rgba(0,0,0,0.05) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0,0,0,0.05) 1px, transparent 1px);
  background-size: 20px 20px;
}

