  <script>
    // Mobile Menu Toggle
    function toggleMobileMenu() {
      const menu = document.getElementById('mobileMenu');
      menu.classList.toggle('open');
    }

    // Accordion Toggle
    function toggleAccordion(item) {
      const allItems = document.querySelectorAll('.accordion-item');
      allItems.forEach(i => {
        if (i !== item) i.classList.remove('open');
      });
      item.classList.toggle('open');
    }

    // News Carousel
    let newsIndex = 0;
    const newsTrack = document.getElementById('newsTrack');
    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');

    function getItemsPerPage() {
      if (window.innerWidth >= 1024) return 3;
      if (window.innerWidth >= 768) return 2;
      return 1;
    }

    function updateCarousel() {
      const itemsPerPage = getItemsPerPage();
      const totalItems = document.querySelectorAll('.news-card').length;
      const maxIndex = Math.max(0, totalItems - itemsPerPage);
      newsIndex = Math.min(newsIndex, maxIndex);

      const cardWidth = 100 / itemsPerPage;
      newsTrack.style.transform = `translateX(-${newsIndex * cardWidth}%)`;

      prevBtn.disabled = newsIndex === 0;
      nextBtn.disabled = newsIndex >= maxIndex;
    }

    function nextNews() {
      const itemsPerPage = getItemsPerPage();
      const totalItems = document.querySelectorAll('.news-card').length;
      const maxIndex = Math.max(0, totalItems - itemsPerPage);
      if (newsIndex < maxIndex) {
        newsIndex++;
        updateCarousel();
      }
    }

    function prevNews() {
      if (newsIndex > 0) {
        newsIndex--;
        updateCarousel();
      }
    }

    // Donate Modal
    let selectedDonationAmount = 25;

    function openDonateModal() {
      document.getElementById('donateModal').classList.add('open');
      document.body.style.overflow = 'hidden';
    }

    function openDonateModalWithAmount(amount) {
      selectPreset(amount, null);
      const presets = document.querySelectorAll('.donation-preset');
      presets.forEach(p => {
        p.classList.toggle('selected', p.textContent === '$' + amount);
      });
      openDonateModal();
    }

    function closeDonateModal() {
      document.getElementById('donateModal').classList.remove('open');
      document.body.style.overflow = '';
    }

    function closeModalOnOverlay(e) {
      if (e.target === e.currentTarget) {
        closeDonateModal();
      }
    }

    function selectPreset(amount, btn) {
      selectedDonationAmount = amount;
      document.getElementById('donateAmount').textContent = '$' + amount;
      document.getElementById('customAmount').value = '';
      document.querySelectorAll('.donation-preset').forEach(p => p.classList.remove('selected'));
      if (btn) btn.classList.add('selected');
    }

    function clearPreset() {
      document.querySelectorAll('.donation-preset').forEach(p => p.classList.remove('selected'));
      selectedDonationAmount = 0;
      document.getElementById('donateAmount').textContent = '';
    }

    function submitDonation() {
      const custom = document.getElementById('customAmount').value;
      const amount = custom || selectedDonationAmount;
      alert('Thank you for your donation of $' + amount + '! This is a demo - in production, this would proceed to payment.');
      closeDonateModal();
    }

    // Scroll animations
    function handleScrollAnimations() {
      const reveals = document.querySelectorAll('.reveal');
      reveals.forEach(el => {
        const windowHeight = window.innerHeight;
        const elementTop = el.getBoundingClientRect().top;
        if (elementTop < windowHeight - 100) {
          el.classList.add('visible');
        }
      });
    }

    // Initialize
    window.addEventListener('load', () => {
      updateCarousel();
      handleScrollAnimations();
    });

    window.addEventListener('resize', updateCarousel);
    window.addEventListener('scroll', handleScrollAnimations);
  </script>
</body>
